#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;     while (t--) {        int n, m;        cin >> n >> m;         string x, s;        cin >> x >> s;         // If already present        if (x.find(s) != string::npos) {            cout << 0 << "\n";            continue;        }         string cur = x;         // We try at most 10 doublings (more than enough for constraints)        for (int ops = 1; ops <= 10; ops++) {            cur += cur;  // REAL operation (doubling)             if (cur.find(s) != string::npos) {                cout << ops << "\n";                goto next_test;            }        }         // If not found        cout << -1 << "\n";         next_test:;    }     return 0;}